import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>У вас есть GIF, который слишком большой для Discord или сайта. Исправление занимает несколько минут, когда вы знаете шаги.</p>\n<p>Это руководство проведёт вас через весь процесс: от выбора пресета до проверки анимации перед отправкой.</p>\n<p>Оно подходит для реакций, записей экрана и GIF для сайта — на ноутбуке или на телефоне.</p>\n<h2 id=\"what-you-need\">Что нужно перед началом</h2>\n<p>Нужен исходный файл GIF. Лучше всего — оригинал, а не копия, пересланная через мессенджер.</p>\n<p>Проверьте лимит места назначения. Discord, Slack и сайты устанавливают разные лимиты — часто 8 или 10 МБ.</p>\n<p>Запишите, где будет использоваться GIF. Для чата важна скорость отправки, а для сайта — вес страницы.</p>\n<p>Сохраните оригинал в безопасности. Никогда не перезаписывайте его сжатой копией, на случай если понадобится попробовать снова.</p>\n<h2 id=\"step-1-open\">Шаг 1: откройте инструмент</h2>\n<p>Откройте <a href=\"/ru/szhat-gif/\">инструмент сжатия GIF</a> в браузере. Аккаунт и установка не нужны.</p>\n<p>Инструмент полностью работает на вашем устройстве. GIF обрабатывается локально и никогда не загружается на сервер.</p>\n<p>Если вы на телефоне, страница работает так же. Нажмите на область загрузки и выберите GIF из галереи или файлов.</p>\n<p>Добавьте страницу в закладки, если часто сжимаете GIF. Это задача, к которой возвращаются постоянно.</p>\n<h2 id=\"step-2-upload\">Шаг 2: загрузите GIF</h2>\n<p>Перетащите файл на страницу или нажмите, чтобы выбрать его. Принимаются анимированные GIF, включая большие файлы на десятки мегабайт.</p>\n<p>Загружайте оригинал самого высокого качества. Сжатие работает лучше, когда исходник чистый.</p>\n<p>Дождитесь завершения загрузки, прежде чем менять настройки. Инструменту нужен полный файл, чтобы показать кадры и палитру.</p>\n<p>Проверьте длительность и число кадров после загрузки. Длинный GIF с сотнями кадров сжимается труднее короткого.</p>\n<h2 id=\"step-3-preset\">Шаг 3: выберите пресет</h2>\n<p>«Лёгкий» применяет мягкое сжатие и сохраняет анимацию плавной. Он подходит для GIF, которые должны оставаться красивыми.</p>\n<p>«Сбалансированный» — пресет по умолчанию. Он уменьшает палитру, обрезает часть кадров и разумно масштабирует.</p>\n<p>«Максимальное сжатие» берёт самый сильный подход. Он подходит для строгих лимитов, например для загрузки в чат.</p>\n<p>Если не уверены, начните со «Сбалансированного» и проверьте результат. Пресет можно сменить и запустить снова.</p>\n<p>Запишите выбранный пресет рядом с названием GIF. В следующий раз вы повторите настройки за секунды.</p>\n<h2 id=\"step-4-adjust\">Шаг 4: настройте палитру и масштаб</h2>\n<p>Палитра 128 цветов подходит большинству GIF. Плоская графика терпит и 64 цвета, а фотографиям нужны 128 или больше.</p>\n<p>Масштаб подбирайте под размер показа. GIF, показанный шириной 400 пикселей, должен быть около 400 пикселей в файле.</p>\n<p>Уменьшение масштаба вдвое — самый сильный рычаг: число пикселей падает вчетверо, а вес файла — больше чем вдвое.</p>\n<p>Для стикеров с прозрачностью держите палитру щедрой. Прозрачные края при маленькой палитре становятся зубчатыми.</p>\n<p>Меняйте по одной настройке за раз. Так вы поймёте, что именно сработало.</p>\n<h2 id=\"step-5-run\">Шаг 5: запустите сжатие</h2>\n<p>Нажмите кнопку запуска и дождитесь завершения. Инструмент обрабатывает кадры один за другим, поэтому большие GIF занимают время.</p>\n<p>Не закрывайте вкладку, пока сжатие выполняется. Закрытие браузера прервёт обработку.</p>\n<p>Следите за индикатором прогресса. Если он остановился на одном месте, подождите минуту: большие файлы обрабатываются дольше.</p>\n<p>Когда сжатие завершено, инструмент покажет исходный и итоговый вес. Сравните их: хорошая экономия для GIF — 50–80 процентов.</p>\n<p>Если результат не укладывается в лимит, смените пресет на «Максимальное сжатие» и запустите снова.</p>\n<h2 id=\"step-6-preview\">Шаг 6: просмотрите анимацию</h2>\n<p>Просмотрите сжатую анимацию целиком, от начала до конца. Вес файла может быть правильным, а анимация — испорченной.</p>\n<p>Смотрите на плавность: дёрганая анимация означает, что удалено слишком много кадров. Повторите с более мягким пресетом.</p>\n<p>Смотрите на цвета: полосы и пятна означают, что палитра слишком мала. Увеличьте её до 128 цветов или больше.</p>\n<p>Смотрите на края: зубчатые прозрачные края означают, что палитра мала для стикера. Держите её щедрой.</p>\n<p>Проверьте GIF в том чате или на той странице, где он будет использоваться. То, что хорошо играет в одном месте, может иначе выглядеть в другом.</p>\n<h2 id=\"step-7-download\">Шаг 7: скачайте и назовите файл</h2>\n<p>Скачайте сжатый GIF и дайте ему понятное имя по содержанию. Имя вроде thumbs-up-reaction.gif лучше, чем GIF-4821.gif.</p>\n<p>Храните оригинал отдельно. Если платформа отклонит сжатую копию, вы сможете сделать новую, не разыскивая исходник.</p>\n<p>Проверьте размер скачанного файла. Он должен быть ниже лимита платформы, с небольшим запасом.</p>\n<p>Загрузите файл на платформу сразу после скачивания. Файл, забытый в папке «Загрузки», легко потерять.</p>\n<p>Проверьте GIF после загрузки на платформу. Убедитесь, что анимация играет и выглядит правильно.</p>\n<h2 id=\"fixing-problems\">Исправление проблем</h2>\n<p>Анимация дёрганая? Удалено слишком много кадров. Повторите с более мягким пресетом или с меньшим удалением кадров.</p>\n<p>Цвета с полосами? Палитра слишком мала. Увеличьте её до 128 цветов или больше, особенно для фотографических GIF.</p>\n<p>Файл всё ещё слишком большой? Уменьшите масштаб вдвое или сократите длительность. Масштаб — самый сильный рычаг.</p>\n<p>Прозрачные края зубчатые? Держите палитру щедрой: прозрачность важнее последних килобайт экономии.</p>\n<p>Ничего не помогает? Рассмотрите видео MP4 вместо GIF: для длинных роликов оно весит в разы меньше.</p>\n<h2 id=\"discord-workflow\">Порядок действий для Discord</h2>\n<p>Проверьте точный лимит Discord перед сжатием. Бесплатный лимит отличается от платного, и GIF должен укладываться именно в ваш лимит.</p>\n<p>Используйте пресет «Максимальное сжатие», если GIF не укладывается в лимит. Для реакций обычно хватает «Сбалансированного» с палитрой 128 цветов.</p>\n<p>Обрежьте GIF плотно вокруг объекта до сжатия. Лицо, заполняющее кадр, читается мгновенно, а широкий кадр тратит момент впустую.</p>\n<p>Проверьте GIF в том канале, где он будет использоваться. Реакция, которая хорошо играет в одном канале, может иначе выглядеть в другом.</p>\n<p>Держите реакции короткими: две-три секунды достаточно, чтобы передать эмоцию.</p>\n<h2 id=\"website-workflow\">Порядок действий для сайта</h2>\n<p>GIF на веб-странице — самый тяжёлый элемент, который она может нести. Один GIF на 10 МБ перевешивает все остальные изображения вместе.</p>\n<p>Ограничьте число GIF на странице. Три зацикленные анимации соревнуются за внимание, а один сфокусированный GIF работает лучше.</p>\n<p>Используйте ленивую загрузку для GIF ниже сгиба. Они не видны при открытии страницы, поэтому браузер может загрузить их позже.</p>\n<p>Добавляйте описательный alt-текст каждому GIF. Поисковики не видят анимацию, они читают её описание.</p>\n<p>Рассмотрите видео вместо GIF для длинных анимаций. Видео весит в разы меньше и даёт тот же эффект.</p>\n<h2 id=\"phone-workflow\">Работа на телефоне</h2>\n<p>На телефоне порядок тот же, но большие GIF обрабатываются медленнее. Разбивайте работу: один GIF за раз, а не партия.</p>\n<p>Берите оригинал из файлов, а не копию из мессенджера. Мессенджеры сжимают GIF ещё до того, как вы их увидите.</p>\n<p>После скачивания проверьте файл в приложении «Файлы». Убедитесь, что размер ниже лимита платформы.</p>\n<p>Держите платформу открытой в другой вкладке браузера. Переключение между вкладками быстрее, чем поиск ссылки заново.</p>\n<p>Если скачивание не началось, проверьте разрешения браузера. Иногда браузер блокирует загрузки, пока вы не разрешите их один раз.</p>\n<h2 id=\"gif-sizes-by-platform\">Размеры GIF по платформам</h2>\n<p>Discord: бесплатный и платный лимиты отличаются — проверьте свой. Обычно речь идёт о 8 или 10 МБ.</p>\n<p>Slack: свои правила и лимиты. Проверьте их перед сжатием, а не после.</p>\n<p>Сайты: лимита нет, но вес страницы решает всё. Один GIF на 10 МБ замедляет страницу для всех посетителей.</p>\n<p>Почта: GIF в письмах должны быть лёгкими, иначе письмо не дойдёт или не откроется.</p>\n<p>Когда сомневаетесь, цельтесь в 8 МБ: этот размер проходит почти везде.</p>\n<h2 id=\"trimming-gifs\">Обрезка GIF</h2>\n<p>Обрезка длительности — сильный рычаг: GIF вдвое короче весит почти вдвое меньше. Уберите скучное начало и конец.</p>\n<p>Обрезка кадра тоже помогает: плотный кадр вокруг объекта тратит меньше пикселей, чем широкий.</p>\n<p>Обрезайте оригинал, а не сжатую копию. Обрезка после сжатия отнимает качество дважды.</p>\n<p>Держите реакции короткими: две-три секунды достаточно. Длинные реакции теряют эффект и весят больше.</p>\n<p>Проверьте обрезанный GIF целиком. Убедитесь, что цикл начинается и заканчивается плавно, без резкого скачка.</p>\n<h2 id=\"preview-tips\">Советы по предпросмотру</h2>\n<p>Просматривайте GIF целиком, от начала до конца. Проблемы часто прячутся в середине анимации.</p>\n<p>Смотрите на реальном экране, где GIF будет показываться. Маленький предпросмотр скрывает дёрганность и полосы.</p>\n<p>Покажите GIF другу, не говоря, что изменилось. Свежий взгляд замечает то, что вы перестали видеть.</p>\n<p>Проверьте цикл: зацикленная анимация должна переходить от конца к началу плавно, без скачка.</p>\n<p>Если цикл рвётся, проверьте первый и последний кадры. Они должны быть похожи, чтобы переход был незаметным.</p>\n<h2 id=\"gif-batch\">Пакетный режим для GIF</h2>\n<p>Пакетный компрессор изображений не подходит для GIF: он работает с обычными изображениями. Сжимайте GIF по одному в инструменте для GIF.</p>\n<p>Если GIF много, обрабатывайте их по одному с одинаковыми настройками. Запишите пресет и палитру, чтобы результаты совпадали.</p>\n<p>Проверяйте каждый GIF после сжатия. Анимации разные, и один пресет не подходит всем одинаково хорошо.</p>\n<p>Называйте файлы по содержанию сразу после скачивания. Имена вроде reaction-laugh.gif найти проще, чем GIF-01.gif.</p>\n<p>Храните оригиналы отдельно. Если понадобится другой размер, свежая копия с оригинала делается за минуту.</p>\n<h2 id=\"gif-quality-scale\">Качество и масштаб GIF</h2>\n<p>Качество GIF — это баланс палитры, кадров и масштаба. Все три рычага влияют на вес и на внешний вид.</p>\n<p>Масштаб — самый сильный рычаг: уменьшение вдвое сокращает число пикселей вчетверо.</p>\n<p>Палитра — второй рычаг: 128 цветов для большинства GIF, 64 — для простой графики, 256 — для фотографий.</p>\n<p>Кадры — третий рычаг: удаление каждого второго кадра вдвое сокращает их число, но делает анимацию дёрганой.</p>\n<p>Настраивайте рычаги по одному. Так вы поймёте, что именно сработало, и сможете повторить это в следующий раз.</p>\n<h2 id=\"when-gif-fails\">Когда GIF не поддаётся</h2>\n<p>Длинные детальные GIF иногда не сжимаются до лимита без потери смысла. Десять секунд видео как GIF — это сотни кадров, и каждый стоит веса.</p>\n<p>В таких случаях сократите длительность или уменьшите масштаб. Если и это не помогает, перейдите на видео MP4.</p>\n<p>Видео MP4 для того же ролика весит в разы меньше: 15 МБ как GIF против 1,5 МБ как MP4.</p>\n<p>Проверьте, нужен ли вообще GIF. Для длинных роликов видео лучше во всём, кроме мгновенного зацикливания в чате.</p>\n<p>Если GIF обязателен, примите компромисс: меньший масштаб и меньшая палитра — цена за попадание в лимит.</p>\n<h2 id=\"gif-future\">Будущее GIF</h2>\n<p>GIF — старый формат, но он живёт: чаты и соцсети любят его за простоту и мгновенное зацикливание.</p>\n<p>WebP и MP4 сжимают лучше, и платформы постепенно их принимают. Но GIF пока что понимают везде без исключений.</p>\n<p>Следите за лимитами платформ: они меняются, и прошлогодние настройки могут не подойти сегодня.</p>\n<p>Тестируйте WebP для анимаций на своём сайте. Он весит меньше GIF и выглядит чище при том же размере.</p>\n<p>А пока что освойте сжатие GIF: этот навык пригодится ещё долго, даже когда форматы сменятся.</p>\n<h2 id=\"keep-practising-gif\">Продолжайте практиковаться</h2>\n<p>Каждый сжатый GIF чему-то учит. Запишите, какой пресет сработал, какая палитра подошла и как изменился вес файла.</p>\n<p>Тестируйте разные пресеты на одном GIF. Сравнение рядом покажет, где проходит граница между качеством и размером.</p>\n<p>Делитесь знаниями с друзьями и командой. Общая заметка с настройками экономит часы каждому.</p>\n<p>Проверяйте GIF в том месте, где он будет использоваться. То, что хорошо играет в одном чате, может иначе выглядеть в другом.</p>\n<p>И помните: лучший GIF — это не самый маленький, а тот, который передаёт идею и при этом загружается быстро.</p>\n<p>Когда готовите GIF для нового чата, начните с одного файла и проверьте его в этом чате. То, что хорошо играет в одном месте, может иначе выглядеть в другом.</p>\n<p>Записывайте, какой пресет сработал для каждого типа GIF. Реакции, записи экрана и анимации для сайта нуждаются в разных настройках.</p>\n<p>Проверяйте лимиты платформ перед каждой отправкой. Бесплатный лимит Discord отличается от платного, а у Slack — свои правила.</p>\n<p>Для длинных анимаций рассмотрите видео вместо GIF. Десять секунд как GIF весят в разы больше, чем те же десять секунд как MP4.</p>\n<p>Держите оригиналы GIF в архиве. Если понадобится другой размер, свежая копия с оригинала делается за минуту.</p>\n<p>Называйте файлы по содержанию сразу после скачивания. Имена вроде reaction-laugh.gif найти проще, чем GIF-01.gif.</p>\n<p>Показывайте GIF друзьям перед публикацией. Свежий взгляд замечает дёрганность и полосы, которые вы перестали видеть.</p>\n<p>Готовый GIF проверьте в том чате, куда его отправите: то, что хорошо играет в одном месте, может иначе выглядеть в другом.</p>\n<p>Для Discord проверьте точный лимит своего аккаунта: бесплатный и платный лимиты отличаются. GIF должен укладываться именно в ваш лимит.</p>\n<p>Обрезка длительности — сильный рычаг: GIF вдвое короче весит почти вдвое меньше. Уберите скучное начало и конец.</p>\n<p>Просматривайте GIF целиком, от начала до конца: проблемы часто прячутся в середине анимации, а не в начале.</p>\n<p>Размеры GIF по платформам отличаются: Discord, Slack, сайты и почта устанавливают свои лимиты. Когда сомневаетесь, цельтесь в 8 МБ.</p>\n<p>Пакетный компрессор изображений не подходит для GIF: он работает с обычными изображениями. Сжимайте GIF по одному в инструменте для GIF.</p>\n<p>Масштаб — самый сильный рычаг: уменьшение вдвое сокращает число пикселей вчетверо, а вес файла — больше чем вдвое.</p>\n<p>Если GIF упорно не укладывается в лимит, перейдите на видео MP4: для длинных роликов оно весит в разы меньше.</p>\n<p>Чек-лист перед отправкой GIF в чат: вес ниже лимита, анимация играет целиком, края чистые, имя файла по содержанию.</p>\n<p>Если GIF нужен для презентации, проверьте его на проекторе: цвета и контраст там отличаются от экрана ноутбука.</p>\n<p>Полное руководство по GIF читайте в статье <a href=\"/ru/blog/kak-szhat-gif-polnoe-rukovodstvo/\">Как сжать GIF: полное руководство</a>. Сравнение с WebP и MP4 — в статье <a href=\"/ru/blog/gif-webp-mp4-sravnenie-animirovannykh-izobrazheniy/\">GIF, WebP и MP4: сравнение анимированных изображений</a>. Для пакетного сжатия фото используйте <a href=\"/ru/paketnoe-szhatie-izobrazheniy/\">пакетный компрессор изображений</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Как сжать GIF для Discord?","answer":"Откройте инструмент сжатия GIF, загрузите файл и выберите пресет «Максимальное сжатие», если GIF не укладывается в лимит. Проверьте точный лимит Discord — бесплатный и платный лимиты отличаются. Просмотрите анимацию целиком перед отправкой."},{"question":"Почему мой GIF выглядит дёрганым после сжатия?","answer":"Потому что удалено слишком много кадров. Повторите сжатие с более мягким пресетом — например, «Сбалансированный» вместо «Максимального сжатия» — или уменьшите удаление кадров. Быстрое действие страдает от удаления кадров сильнее всего."},{"question":"Можно ли сжать GIF без потери качества?","answer":"Полностью без потерь — нет: сжатие GIF всегда что-то меняет. Но при правильных настройках потери почти незаметны: используйте пресет «Лёгкий» или «Сбалансированный», палитру 128 цветов и масштаб под размер показа."},{"question":"Какая палитра лучше всего подходит для записи экрана в GIF?","answer":"128 цветов с пресетом «Сбалансированный». Графика интерфейса терпит маленькие палитры, а текст остаётся читаемым. Записывайте с частотой 15 кадров в секунду: этого достаточно для интерфейса и вдвое меньше тридцати."},{"question":"Насколько маленьким может стать GIF?","answer":"Зависит от длительности, размеров и содержимого. Короткий GIF с плоской графикой может ужаться в десятки раз, а длинный фотографический GIF — лишь в два-три раза. Масштаб — самый сильный рычаг: уменьшение вдвое сокращает число пикселей вчетверо."},{"question":"Удаляет ли сжатие GIF его прозрачность?","answer":"Нет, если вы не меняете формат: прозрачность сохраняется. Но уменьшение палитры может сделать прозрачные края грубыми. Для стикеров держите палитру щедрой — 128 цветов или больше — чтобы края оставались чистыми."}];
